import React, { useEffect } from "react";
import SidebarMenu from "./SidebarMenu";
import { useLocation } from "react-router-dom";

const Layout = ({ children }) => {
  const location = useLocation();
  const hideSidebar = location.pathname === "/auth/login";

  useEffect(() => {
    if (window.$) {
      window.$(() =>
        window.$(".nav-sidebar").each(function () {
          window.$(this).treeview();
        })
      );
    }
  }, []);

  return (
    <div className="wrapper hold-transition sidebar-mini layout-fixed">
      {/* NAVBAR */}
      {!hideSidebar && (
        <nav className="main-header navbar navbar-expand navbar-white navbar-light">
          <ul className="navbar-nav">
            <li className="nav-item">
              <a
                className="nav-link"
                data-widget="pushmenu"
                href="#"
                role="button"
              >
                <i className="fas fa-bars"></i>
              </a>
            </li>
          </ul>
        </nav>
      )}

      {/* SIDEBAR */}
      {!hideSidebar && <SidebarMenu />}

      {/* CONTENT */}
      <div className="content-wrapper">
        <section className="content pt-3">{children}</section>
      </div>

      {/* FOOTER */}
      {!hideSidebar && (
        <footer className="main-footer text-sm">
          <strong>© 2025 ORA Platform.</strong> All rights reserved.
        </footer>
      )}
    </div>
  );
};

export default Layout;
